using Microsoft.EntityFrameworkCore;
using RaceDay.Api.Models;

namespace RaceDay.Api.Data;

/// <summary>
/// EF Core Code-First context. Table names, column names, types, keys, defaults, CHECK constraints
/// and foreign-key constraint names all mirror docs/RaceDay_Schema.sql from Part 1, so the database
/// generated by the migration is the same database the SQL script creates.
/// </summary>
public class RaceDayDbContext : DbContext
{
    public RaceDayDbContext(DbContextOptions<RaceDayDbContext> options) : base(options) { }

    public DbSet<User> Users => Set<User>();
    public DbSet<Event> Events => Set<Event>();
    public DbSet<Category> Categories => Set<Category>();
    public DbSet<Enrolment> Enrolments => Set<Enrolment>();
    public DbSet<Result> Results => Set<Result>();
    public DbSet<EventRoute> Routes => Set<EventRoute>();
    public DbSet<EventAnnouncement> EventAnnouncements => Set<EventAnnouncement>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        // ---------------- Users ----------------
        modelBuilder.Entity<User>(e =>
        {
            e.ToTable("Users", t =>
            {
                t.HasCheckConstraint("CK_Users_Role", "[role] IN ('Organiser', 'Participant')");
                t.HasCheckConstraint("CK_Users_Gender", "[gender] IN ('Male', 'Female', 'Other') OR [gender] IS NULL");
            });
            e.HasIndex(u => u.Email).IsUnique().HasDatabaseName("UQ_Users_Email");
            e.Property(u => u.CreatedAt).HasDefaultValueSql("GETDATE()");
            e.Property(u => u.UpdatedAt).HasDefaultValueSql("GETDATE()");
        });

        // ---------------- Events ----------------
        modelBuilder.Entity<Event>(e =>
        {
            e.ToTable("Events", t =>
            {
                t.HasCheckConstraint("CK_Events_EventType", "[event_type] IN ('Running', 'Walking', 'Cycling')");
                t.HasCheckConstraint("CK_Events_Status", "[status] IN ('Draft', 'Published', 'Completed', 'Cancelled')");
            });
            e.Property(ev => ev.Status).HasDefaultValue(EventStatuses.Draft);
            e.Property(ev => ev.CreatedAt).HasDefaultValueSql("GETDATE()");
            e.Property(ev => ev.UpdatedAt).HasDefaultValueSql("GETDATE()");

            e.HasOne(ev => ev.Organiser)
                .WithMany(u => u.OrganisedEvents)
                .HasForeignKey(ev => ev.OrganiserId)
                .OnDelete(DeleteBehavior.NoAction)
                .HasConstraintName("FK_Events_Organiser");
        });

        // ---------------- Categories ----------------
        modelBuilder.Entity<Category>(e =>
        {
            e.ToTable("Categories", t =>
                t.HasCheckConstraint("CK_Categories_GenderRestriction",
                    "[gender_restriction] IN ('Male', 'Female') OR [gender_restriction] IS NULL"));
            e.Property(c => c.EntryFee).HasDefaultValue(0.00m);

            e.HasOne(c => c.Event)
                .WithMany(ev => ev.Categories)
                .HasForeignKey(c => c.EventId)
                .OnDelete(DeleteBehavior.Cascade)
                .HasConstraintName("FK_Categories_Event");
        });

        // ---------------- Enrolments ----------------
        modelBuilder.Entity<Enrolment>(e =>
        {
            e.ToTable("Enrolments", t =>
                t.HasCheckConstraint("CK_Enrolments_Status", "[status] IN ('Pending', 'Confirmed', 'Cancelled')"));
            e.Property(en => en.EnrolmentDate).HasDefaultValueSql("GETDATE()");
            e.Property(en => en.Status).HasDefaultValue(EnrolmentStatuses.Pending);
            e.HasIndex(en => new { en.ParticipantId, en.CategoryId }).IsUnique().HasDatabaseName("UQ_Enrolment_Unique");

            e.HasOne(en => en.Participant)
                .WithMany(u => u.Enrolments)
                .HasForeignKey(en => en.ParticipantId)
                .OnDelete(DeleteBehavior.NoAction)
                .HasConstraintName("FK_Enrolments_Participant");

            e.HasOne(en => en.Category)
                .WithMany(c => c.Enrolments)
                .HasForeignKey(en => en.CategoryId)
                .OnDelete(DeleteBehavior.Cascade)
                .HasConstraintName("FK_Enrolments_Category");
        });

        // ---------------- Results ----------------
        modelBuilder.Entity<Result>(e =>
        {
            e.ToTable("Results", t =>
                t.HasCheckConstraint("CK_Results_Status", "[status] IN ('Finished', 'DNF', 'DNS', 'DQ')"));
            e.Property(r => r.RecordedAt).HasDefaultValueSql("GETDATE()");
            e.HasIndex(r => r.EnrolmentId).IsUnique().HasDatabaseName("UQ_Results_Enrolment");

            e.HasOne(r => r.Enrolment)
                .WithOne(en => en.Result)
                .HasForeignKey<Result>(r => r.EnrolmentId)
                .OnDelete(DeleteBehavior.Cascade)
                .HasConstraintName("FK_Results_Enrolment");

            e.HasOne(r => r.RecordedBy)
                .WithMany(u => u.RecordedResults)
                .HasForeignKey(r => r.RecordedById)
                .OnDelete(DeleteBehavior.NoAction)
                .HasConstraintName("FK_Results_RecordedBy");
        });

        // ---------------- Routes ----------------
        modelBuilder.Entity<EventRoute>(e =>
        {
            e.ToTable("Routes");
            e.HasIndex(r => r.EventId).IsUnique().HasDatabaseName("UQ_Routes_Event");

            e.HasOne(r => r.Event)
                .WithOne(ev => ev.Route)
                .HasForeignKey<EventRoute>(r => r.EventId)
                .OnDelete(DeleteBehavior.Cascade)
                .HasConstraintName("FK_Routes_Event");
        });

        // ---------------- EventAnnouncements ----------------
        modelBuilder.Entity<EventAnnouncement>(e =>
        {
            e.ToTable("EventAnnouncements", t =>
                t.HasCheckConstraint("CK_EventAnnouncements_Priority", "[priority] IN ('Low', 'Normal', 'High', 'Urgent')"));
            e.Property(a => a.Priority).HasDefaultValue(AnnouncementPriorities.Normal);
            e.Property(a => a.CreatedAt).HasDefaultValueSql("GETDATE()");

            e.HasOne(a => a.Event)
                .WithMany(ev => ev.Announcements)
                .HasForeignKey(a => a.EventId)
                .OnDelete(DeleteBehavior.Cascade)
                .HasConstraintName("FK_Announcements_Event");

            e.HasOne(a => a.Author)
                .WithMany(u => u.Announcements)
                .HasForeignKey(a => a.AuthorId)
                .OnDelete(DeleteBehavior.NoAction)
                .HasConstraintName("FK_Announcements_Author");
        });

        SeedData.Apply(modelBuilder);
    }
}
